"""Local-only fixture server. No fixture code is bundled in either release."""
from http.server import ThreadingHTTPServer,SimpleHTTPRequestHandler
from pathlib import Path
import os
ROOT=Path(__file__).resolve().parents[1]
os.chdir(ROOT/'android/web')
class QA(SimpleHTTPRequestHandler):
 def do_GET(self):
  if self.path.split('?')[0]=='/mobile.js':
   text=Path('mobile.js').read_text(encoding='utf8')
   fixture=r"""screen='title';const scenario=new URLSearchParams(location.search).get('scenario');if(['shop','boss','misprints','cursed'].includes(scenario)){await command('new',{character:0,replace:true});if(scenario==='misprints')await py.runPythonAsync("import content;content.ART_INFO['faulty_printer']['amount']=100;r=mobile_backend.run;r['artifacts']=r['artifacts']+['faulty_printer'];r.setdefault('card_mods',{}).update({str(i):[200,-300,[32,8192,2,16384][i%4],[4,16,2,1][i%4]] for i,cid in enumerate(r['pool'][:16]) if mobile_backend.g.BY_ID[cid]['data']['type']&1 and i%2==0})");await py.runPythonAsync("mobile_backend.run.update(stage='shop',gold=999,round=5,gold_leaving_shop=9999)\nmobile_backend.g.restock(mobile_backend.run)\nmobile_backend.g.routes(mobile_backend.run)");if(scenario==='cursed')await py.runPythonAsync('import cursed_relics;cursed_relics.create_offer(mobile_backend.run)');state=JSON.parse(await py.runPythonAsync('mobile_backend.json.dumps(mobile_backend.state())'));screen=scenario==='boss'?'routes':'shop'}if(['won','lost'].includes(scenario)){const won=scenario==='won',level=Number(new URLSearchParams(location.search).get('level')??(won?3:2));await command('new',{character:0,replace:true});await py.runPythonAsync(`import time\nr=mobile_backend.run;now=time.time();won=${won?'True':'False'};level=${level}\nr.update(character=0 if won else 35,stage='complete' if won else 'gameover',round=9 if won else 7,challenge_level=level,gold=360 if won else 292,lp=3200 if won else 0,started_at=now-(4440 if won else 3120),finished_at=now,level_unlocked=level+1 if won and level<6 else None)\nr['stats']=dict(damage_dealt=71350 if won else 49700,attacks_declared=52 if won else 33,monsters_summoned=41 if won else 28,cards_activated=37 if won else 28,bosses_defeated=3 if won else 2,packs_bought=22 if won else 17,coins_earned=2140 if won else 1384,coins_spent=1780 if won else 1032)\nr['selected']=list(range(min(40,len(r['pool']))))\nr['artifacts']=['dragon','dragon','light','halo','buckler','sword','normal','tribute','chalice','interest','prism','eye','flame','ankh'] if won else ['pierce','blade','fossil','earth','light','light','gear','buckler','sword','spring','map','interest','satchel','bandage','chalice','tribute']\nops,lps=([18,10,4,16,15,6,14,3,11],[7600,6900,5200,6100,4800,3900,5500,4700,3200]) if won else ([22,8,58,54,20,47,45,41],[7800,4400,3500,2500,1500,4900,3900,0])\nr['timeline']=[dict(duel=i+1,loop=1,opponent=o,won=won or i<7,lp_before_healing=lp,lp_after_healing=lp,coins=40,turns=7) for i,(o,lp) in enumerate(zip(ops,lps))]\nif not won:r['loss']=dict(text='Defeated by the effect of Magic Cylinder — 2,975 damage',card=62279055,damage=2975,reason=1)`);state=JSON.parse(await py.runPythonAsync('mobile_backend.json.dumps(mobile_backend.state())'));screen='ending'}render();await notices();"""
   # Scenarios start right after loading finishes, in place of the title screen.
   anchor="screen='title';render();await notices();"
   assert anchor in text,'mobile.js startup changed; update the QA fixture'
   text=text.replace(anchor,fixture,1)
   data=text.encode();self.send_response(200);self.send_header('Content-Type','text/javascript; charset=utf-8');self.end_headers();self.wfile.write(data)
  else:super().do_GET()
QA.extensions_map.update({'.js':'text/javascript','.mjs':'text/javascript','.wasm':'application/wasm'})
ThreadingHTTPServer(('127.0.0.1',4191),QA).serve_forever()
